"use client";
import confetti from "canvas-confetti";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Gift, MessageCircleHeart, Mic, Sparkles, Wind } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { birthdayConfig } from "@/lib/birthday-config";
import { Cake } from "./Cake";
import { FloatingParticles } from "./FloatingParticles";
import { MusicControl } from "./MusicControl";

type Stage = "welcome" | "gift" | "cake" | "wish" | "final";
const flowers = ["✦","✿","♡","✾","✧","❀","♥"];
export function BirthdayExperience() {
 const [stage,setStage]=useState<Stage>("welcome"), [blown,setBlown]=useState(false), [mic,setMic]=useState<"idle"|"listening"|"denied">("idle"); const [wish]=useState(() => birthdayConfig.wishes[Math.floor(Math.random() * birthdayConfig.wishes.length)]); const reduced=useReducedMotion(); const stream=useRef<MediaStream|null>(null);
 const celebrate=useCallback(() => { if (!reduced) { confetti({ particleCount: 120, spread: 75, origin:{y:.62}, colors:["#ffe4a8","#f9a8d4","#c4b5fd","#ffffff"] }); setTimeout(()=>confetti({particleCount:70,angle:60,spread:60,origin:{x:0}}),400); } setTimeout(()=>setStage("final"),1300); },[reduced]);
 const blow=useCallback(()=>{ if(blown) return; setBlown(true); stream.current?.getTracks().forEach(t=>t.stop()); setMic("idle"); setStage("wish"); setTimeout(celebrate,1200); },[blown,celebrate]);
 const startMic=async()=>{ try { const s=await navigator.mediaDevices.getUserMedia({audio:true}); stream.current=s; setMic("listening"); const analyser=new AudioContext().createAnalyser(), source=new AudioContext().createMediaStreamSource(s); source.connect(analyser); const data=new Uint8Array(analyser.fftSize); const check=()=>{ analyser.getByteTimeDomainData(data); const v=data.reduce((n,x)=>n+Math.abs(x-128),0)/data.length; if(v>12) blow(); else if(!blown) requestAnimationFrame(check); }; check(); } catch { setMic("denied"); } };
 useEffect(()=>()=>stream.current?.getTracks().forEach(t=>t.stop()),[]);
 return <div className={`experience ${stage}`}><FloatingParticles /><MusicControl />
  {stage === "final" && <div className="flower-rain" aria-hidden="true">{Array.from({length:32},(_,i)=><i key={i} style={{left:`${(i*23)%100}%`,animationDelay:`${-(i%9)*.55}s`}}>{flowers[i%flowers.length]}</i>)}</div>}
  <AnimatePresence mode="wait">
   {stage === "welcome" && <Scene key="welcome"><Eyebrow>pour quelqu’un d’exceptionnel</Eyebrow><h1>Une petite<br/><em>surprise</em> t’attend…</h1><p>Prends un instant, cette expérience est juste pour toi.</p><Primary onClick={()=>setStage("gift")}><Gift size={18}/>Découvrir ma surprise</Primary></Scene>}
   {stage === "gift" && <Scene key="gift"><motion.div className="gift" animate={{rotate:[-2,2,-2],y:[0,-10,0]}} transition={{duration:3,repeat:Infinity}}><div className="ribbon v"/><div className="ribbon h"/><div className="gift-lid"/></motion.div><Eyebrow>un petit mystère</Eyebrow><h2>Prêt(e) à découvrir<br/>ce qui t’attend ?</h2><Primary onClick={()=>setStage("cake")}><Sparkles size={18}/>Ouvrir le cadeau</Primary></Scene>}
   {(stage === "cake" || stage === "wish") && <Scene key="cake"><Cake blown={blown}/>{stage === "cake" && <><Eyebrow>ferme les yeux un instant</Eyebrow><h2>Fais un vœu… <span>✨</span></h2><p>Quand tu es prêt(e), souffle les bougies.</p><div className="actions"><button className="mic-button" onClick={startMic} disabled={mic==="listening"}><Mic size={18}/>{mic==="listening" ? "J’écoute ton souffle…" : "Utiliser le micro"}</button><button className="soft-button" onClick={blow}><Wind size={18}/>Souffler les bougies</button></div>{mic==="denied" && <small>Le micro n’est pas disponible — utilise simplement le bouton de souffle.</small>}</>}{stage === "wish" && <motion.div initial={{opacity:0,y:15}} animate={{opacity:1,y:0}}><Eyebrow>chut…</Eyebrow><h2>Vœu accepté… ✨</h2></motion.div>}</Scene>}
   {stage === "final" && <Scene key="final"><Eyebrow>une journée rien que pour toi</Eyebrow><motion.h1 initial={{opacity:0,y:25}} animate={{opacity:1,y:0}}>Joyeux anniversaire<br/><em>{birthdayConfig.name}</em> <span>❤️</span></motion.h1><motion.div className="portrait" initial={{opacity:0,scale:.65,rotate:-8}} animate={{opacity:1,scale:1,rotate:0}} transition={{delay:.22,type:"spring",stiffness:160,damping:13}}>{birthdayConfig.photo ? <img src={birthdayConfig.photo} alt={`Portrait de ${birthdayConfig.name}`}/> : <span>{birthdayConfig.name.split(" ").map(x=>x[0]).join("")}</span>}</motion.div><motion.p className="message" initial={{opacity:0,y:14}} animate={{opacity:1,y:0}} transition={{delay:.45}}>{wish}</motion.p>{birthdayConfig.gallery.length > 0 && <div className="gallery" aria-label="Souvenirs en photo">{birthdayConfig.gallery.map((src,index)=><motion.img key={src} src={src} alt={`Souvenir ${index+1} de ${birthdayConfig.name}`} initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:.6+index*.1}}/>)}</div>}<motion.p className="signature" initial={{opacity:0}} animate={{opacity:1}} transition={{delay:.8}}>{birthdayConfig.signature}</motion.p><motion.a className="message-link" href={`https://wa.me/${birthdayConfig.whatsappPhone}?text=${encodeURIComponent("Merci pour cette magnifique surprise ❤️")}`} target="_blank" rel="noreferrer" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:1}}><MessageCircleHeart size={18}/>Laisser un message WhatsApp</motion.a><div className="final-flower">✿　✦　❀　✦　✿</div></Scene>}
  </AnimatePresence></div>
}
function Scene({children}:{children:React.ReactNode}) { return <motion.section className="scene" initial={{opacity:0,scale:.98,y:12}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:1.02,y:-8}} transition={{duration:.55}}>{children}</motion.section> }
function Eyebrow({children}:{children:React.ReactNode}) {return <div className="eyebrow"><span/> {children} <span/></div>}
function Primary({children,onClick}:{children:React.ReactNode,onClick:()=>void}) {return <button className="primary" onClick={onClick}>{children}</button>}
